import { memo } from 'react'
import { formatCellLabel } from '../../lib/format'
import type { GridCell } from '../../lib/overlap'
import type { TimeFormat } from '../../lib/types'
import { cellState, describeCell } from './cellInfo'

interface HourCellProps {
  cityId: string
  cityName: string
  cell: GridCell
  format: TimeFormat
  /** `compact` stacks the hour over AM/PM for the 24-column desktop grid; `wide` is one line for mobile. */
  layout: 'compact' | 'wide'
  hovered?: boolean
  isNow?: boolean
  onHover?: (refHour: number) => void
}

export const HourCell = memo(function HourCell({
  cityId,
  cityName,
  cell,
  format,
  layout,
  hovered = false,
  isNow = false,
  onHover,
}: HourCellProps) {
  const { main, suffix } = formatCellLabel(cell.localMinutes, format)
  const description = describeCell(cityName, cell, format)
  const state = cellState(cell)
  const isMidnight = Math.floor(cell.localMinutes / 60) === 0
  const hasMinutes = cell.localMinutes % 60 !== 0

  if (layout === 'wide') {
    const dayLabel = cell.dayShift === 0 ? null : cell.dayShift > 0 ? `+${cell.dayShift}d` : `${cell.dayShift}d`
    return (
      <div
        role="cell"
        title={description}
        aria-label={description}
        data-testid="hour-cell"
        data-city={cityId}
        data-hour={cell.refHour}
        data-state={state}
        data-midnight={isMidnight}
        data-now={isNow}
        data-layout="wide"
        className="hour-cell h-10 gap-1.5 text-sm"
      >
        <span>{main}</span>
        {suffix && <span className="text-[10px] font-semibold opacity-75">{suffix}</span>}
        {dayLabel && <span className="absolute right-2 text-[10px] font-semibold opacity-70">{dayLabel}</span>}
      </div>
    )
  }

  return (
    <div
      role="cell"
      title={description}
      aria-label={description}
      data-testid="hour-cell"
      data-city={cityId}
      data-hour={cell.refHour}
      data-state={state}
      data-midnight={isMidnight}
      data-hover={hovered}
      data-layout="compact"
      onMouseEnter={onHover && (() => onHover(cell.refHour))}
      className="hour-cell h-12 flex-col gap-[3px]"
    >
      <span className={hasMinutes ? 'text-[9px] @4xl:text-[11px]' : 'text-xs @4xl:text-sm'}>{main}</span>
      {suffix && <span className="text-[8px] font-semibold leading-none opacity-75 @4xl:text-[9px]">{suffix}</span>}
    </div>
  )
})

