@import 'tailwindcss';

/*
 * Design tokens. Green is reserved for overlap and nothing else, so it reads
 * as a signal. Indigo marks interaction and the reference city.
 */
:root {
  color-scheme: light dark;

  --canvas: #f4f3ee;
  --surface: #ffffff;
  --surface-2: #f8f7f3;
  --line: #e4e1d8;
  --line-strong: #cfcbbf;

  --ink: #17181c;
  --ink-2: #4f525b;
  --ink-3: #82858f;

  --accent: #4338ca;
  --accent-soft: #e9e7fb;
  --accent-ink: #ffffff;

  --overlap-bg: #3fd68a;
  --overlap-ink: #04261a;
  --overlap-soft: #d5f7e5;
  --overlap-soft-ink: #0b5a37;
  --awake-bg: #e8e5d9;
  --awake-ink: #2a2c33;
  --sleep-bg: #ffffff;
  --sleep-stripe: #ebe8df;
  --sleep-ink: #b4b1a6;

  --warn-bg: #fff3d6;
  --warn-ink: #7a4a00;
  --warn-line: #f0d08a;

  --card-shadow: 0 1px 2px rgb(23 24 28 / 0.04), 0 8px 24px -12px rgb(23 24 28 / 0.12);
}

@media (prefers-color-scheme: dark) {
  :root {
    --canvas: #0c0d11;
    --surface: #15171d;
    --surface-2: #1b1e25;
    --line: #272a33;
    --line-strong: #3a3e4a;

    --ink: #eceef3;
    --ink-2: #a5a9b5;
    --ink-3: #6f7480;

    --accent: #a5a6ff;
    --accent-soft: #24264a;
    --accent-ink: #12132b;

    --overlap-bg: #3fd68a;
    --overlap-ink: #04261a;
    --overlap-soft: #0f3324;
    --overlap-soft-ink: #7df0b5;
    --awake-bg: #2c303b;
    --awake-ink: #e6e8ef;
    --sleep-bg: #15171d;
    --sleep-stripe: #1e2129;
    --sleep-ink: #4a4f5b;

    --warn-bg: #2b2212;
    --warn-ink: #f5c56b;
    --warn-line: #5a4519;

    --card-shadow: 0 1px 2px rgb(0 0 0 / 0.3), 0 8px 24px -12px rgb(0 0 0 / 0.5);
  }
}

@theme inline {
  --font-sans: 'Inter Variable', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;

  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-accent: var(--accent);
  --color-accent-soft: var(--accent-soft);
  --color-accent-ink: var(--accent-ink);
  --color-overlap: var(--overlap-bg);
  --color-overlap-ink: var(--overlap-ink);
  --color-overlap-soft: var(--overlap-soft);
  --color-overlap-soft-ink: var(--overlap-soft-ink);
  --color-awake: var(--awake-bg);
  --color-warn: var(--warn-bg);
  --color-warn-ink: var(--warn-ink);
  --color-warn-line: var(--warn-line);

  --shadow-card: var(--card-shadow);
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    margin: 0;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-sans);
    font-feature-settings: 'tnum' 1, 'cv11' 1;
    -webkit-font-smoothing: antialiased;
  }

  button,
  select,
  input {
    font: inherit;
    color: inherit;
  }

  button {
    cursor: pointer;
  }

  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

/* ---------- Grid cells: three states, one component ---------- */

.hour-cell {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  border-radius: 6px;
  line-height: 1;
  user-select: none;
  transition:
    background-color 120ms ease,
    color 120ms ease;
}

.hour-cell[data-state='sleep'] {
  background-color: var(--sleep-bg);
  background-image: repeating-linear-gradient(
    135deg,
    transparent 0 4px,
    var(--sleep-stripe) 4px 5px
  );
  color: var(--sleep-ink);
  font-weight: 500;
}

.hour-cell[data-state='awake'] {
  background-color: var(--awake-bg);
  color: var(--awake-ink);
  font-weight: 500;
}

.hour-cell[data-state='overlap'] {
  background-color: var(--overlap-bg);
  color: var(--overlap-ink);
  font-weight: 800;
  box-shadow: inset 0 0 0 1px rgb(4 38 26 / 0.18);
}

.hour-cell[data-hover='true'] {
  outline: 2px solid color-mix(in srgb, var(--ink) 60%, transparent);
  outline-offset: -2px;
  z-index: 1;
}

/* Local midnight: a notch marking where a new calendar day starts in that city. */
.hour-cell[data-midnight='true']::before {
  content: '';
  position: absolute;
  background: var(--accent);
  border-radius: 2px;
  left: 0;
  top: 5px;
  bottom: 5px;
  width: 2px;
}

.hour-cell[data-layout='wide'][data-midnight='true']::before {
  left: 6px;
  right: 6px;
  top: 0;
  bottom: auto;
  width: auto;
  height: 2px;
}

.hour-head[data-now='true'] {
  background: var(--ink);
  color: var(--canvas);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

