    document.querySelectorAll('[data-testid=hour-cell]').forEach((cell) => {
      const cw = cell.getBoundingClientRect().width
      cell.querySelectorAll('span').forEach((s) => {
        if (s.getBoundingClientRect().width > cw + 0.5) bad.push([cell.dataset.city, s.textContent, Math.round(s.getBoundingClientRect().width * 10) / 10, Math.round(cw * 10) / 10])
      })
    })
    return {
      cellW: cell.getBoundingClientRect().width,
      bad,
      docOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      layout: document.querySelectorAll('[data-testid=city-row]').length,
    }
  })
  check('768 uses desktop layout', info.layout === 5, JSON.stringify(info.layout))
  check('768 no doc overflow', info.docOverflow === 0, String(info.docOverflow))
  check('768 no label overflow', info.bad.length === 0, `cellW=${info.cellW} ` + JSON.stringify(info.bad.slice(0, 6)))
  await page.screenshot({ path: 'scratch/flow-768.png', fullPage: true })
  await context.close()
}

// ---------- 767 => mobile layout ----------
for (const width of [767, 390, 320]) {
  const { page, context, errors } = await fresh(width, 800)
  const info = await page.evaluate(() => ({
    rows: document.querySelectorAll('[data-testid=city-row]').length,
    cols: document.querySelectorAll('[data-testid=city-column]').length,
    hourRows: document.querySelectorAll('[data-testid=hour-row]').length,
    docOverflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
  }))
  check(`${width}: mobile layout (3 columns, 24 rows, no desktop rows)`, info.rows === 0 && info.cols === 3 && info.hourRows === 24, JSON.stringify(info))
  check(`${width}: no page-level horizontal overflow`, info.docOverflow === 0, String(info.docOverflow))

  // header stays pinned while the table scrolls
  const pinned = await page.evaluate(async () => {
    const table = document.querySelector('[role=table]')
    const header = document.querySelector('[data-testid=city-column]')
    const before = header.getBoundingClientRect().top - table.getBoundingClientRect().top
    table.scrollTop = 300
    await new Promise((r) => setTimeout(r, 50))
    const after = header.getBoundingClientRect().top - table.getBoundingClientRect().top
    return { before, after, scrollable: table.scrollHeight > table.clientHeight }
  })
  check(`${width}: sticky header`, Math.abs(pinned.before - pinned.after) < 1 && pinned.scrollable, JSON.stringify(pinned))

  if (width === 390) {
    // interactions on mobile
    await page.getByRole('button', { name: /add city/i }).click()
    const box = await page.getByRole('combobox').boundingBox()
    check('390: picker inside viewport', box.x >= 0 && box.x + box.width <= 390, JSON.stringify(box))
    await page.getByRole('combobox').fill('mumbai')
    await page.keyboard.press('Enter')
    check('390: add city on mobile', (await page.locator('[data-testid=city-column]').count()) === 4)
    const overflowCols = await page.evaluate(() => {
      const t = document.querySelector('[role=table]')
      return { scrollW: t.scrollWidth, clientW: t.clientWidth }
    })
    console.log('    table scroll size', JSON.stringify(overflowCols))
    await page.locator('[data-city=denpasar][data-testid=city-column] [data-testid=city-name]').click()
    const first = await page.locator('[data-testid=city-column] [data-testid=city-name]').first().textContent()
    check('390: promote on mobile', first === 'Denpasar', first)
    await page.getByRole('button', { name: 'Remove Geneva' }).click()
    check('390: remove on mobile', (await page.locator('[data-testid=city-column]').count()) === 3)
    await page.getByRole('button', { name: 'Base', exact: true }).click()
    await page.screenshot({ path: 'scratch/flow-390-base.png', fullPage: true })
  }
  check(`${width}: no console errors`, errors.length === 0, errors.join(' | '))
  await context.close()
}

// ---------- Dark mode contrast sanity ----------
{
  const { page, context } = await fresh(1440, 900, 'dark')
  const colors = await page.evaluate(() => {
    const pick = (state) => {
      const el = document.querySelector(`[data-testid=hour-cell][data-state=${state}]`)
      const s = getComputedStyle(el)
      return { bg: s.backgroundColor, fg: s.color, weight: s.fontWeight }
    }
    return { overlap: pick('overlap'), awake: pick('awake'), sleep: pick('sleep'), body: getComputedStyle(document.body).backgroundColor }
  })
  console.log('    dark colors', JSON.stringify(colors))
  await page.screenshot({ path: 'scratch/flow-dark.png', fullPage: true })
  await context.close()
}

await browser.close()
console.log(failures === 0 ? '\nALL FLOWS PASSED' : `\n${failures} FAILURES`)
process.exit(failures === 0 ? 0 : 1)

