import { chromium } from 'playwright-core'

const browser = await chromium.launch({ channel: 'chrome' })
for (const [width, scheme] of [[390, 'light'], [1440, 'light'], [1440, 'dark']]) {
  const context = await browser.newContext({ viewport: { width, height: 900 }, colorScheme: scheme })
  const page = await context.newPage()
  await page.goto('http://127.0.0.1:9364/')
  await page.waitForSelector('h1')
  const out = await page.evaluate(() => {
    const st = (el) => {
      const s = getComputedStyle(el)
      return { bg: s.backgroundColor, fg: s.color }
    }
    const add = [...document.querySelectorAll('button')].find((b) => b.textContent.includes('Add city'))
    const settings = [...document.querySelectorAll('button')].find((b) => b.textContent.includes('Settings'))
