    const range = document.querySelector('[data-testid=overlap-range]')
    const ref = document.querySelector('[data-testid=ref-badge]')
    return { add: st(add), settings: st(settings), modeActive: st(mode), range: st(range), ref: st(ref) }
  })
  console.log(width, scheme, JSON.stringify(out))
  await context.close()
}
await browser.close()

